import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Initialize c with valid parameters so that reference currentVersion() would work.
        // We need a real oracle contract; deploy a minimal one.
        MockOracle oracle = new MockOracle();
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS, PayoffDefinitionLib.PayoffDirection.ZERO, bytes30(0)),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(1e16),
            makerFee: UFixed18.wrap(1e16),
            takerFee: UFixed18.wrap(1e16),
            positionFee: UFixed18.wrap(1e16),
            makerLimit: UFixed18.wrap(1e20),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(1),
                maxRate: PackedFixed18.wrap(2),
                targetRate: PackedFixed18.wrap(1),
                targetUtilization: PackedUFixed18.wrap(1e17)
            })
        });
        vm.prank(actor);
        c.initialize(info);

        // currentVersion() calls oracle().currentVersion().
        // With reference: returns a valid OracleVersion. With bug: oracle() returns address(0), call reverts.
        bool ok;
        try c.currentVersion() returns (IOracleProvider.OracleVersion memory) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MockOracle is IOracleProvider {
    function sync() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
}

