contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(PayoffDefinition calldata payoffDef) public {
        // Fuzzer supplies any PayoffDefinition (including zero/default)
        // We must initialize the product because payoffDefinition() reads from storage that is set during __UPayoffProvider__initialize
        // For the test, we need a controller, so we deploy a minimal one and impersonate it.
        // But C's initialize is initializer(1) and expects msg.sender to be a contract (isContract check in __UControllerProvider__initialize).
        // So we deploy a helper Controller that can initialize C.
