pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(int256 rawPrice) public {
        // Keep the raw price in a reasonable range (e.g. non-zero, not extreme)
        vm.assume(rawPrice > 0 && rawPrice < 1e30);
        // Deploy a mock oracle that returns the fuzzed raw price
        MockOracle oracle = new MockOracle(rawPrice);
        // Initialize the product with a payoff definition that transforms the price (e.g., 2x)
        // We need to call initialize, but C's initialize expects a ProductInfo struct.
        // We can't directly call initialize because it requires msg.sender to be a controller.
        // Instead, we deploy a minimal controller to pass the check.
        MockController controller = new MockController(address(this));
        vm.prank(address(controller));
        c.initialize(IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.NONE,
                data: bytes30(0)
            }),
            oracle: oracle,
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(1e17),
            makerFee: UFixed18.wrap(1e16),
            takerFee: UFixed18.wrap(1e16),
            positionFee: UFixed18.wrap(1e16),
            makerLimit: UFixed18.wrap(10000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        }));
        // Now call currentVersion and check the price matches the transformed raw price
        IOracleProvider.OracleVersion memory v = c.currentVersion();
        // Because the payoff is PASSTHROUGH with NONE direction, transform should return the same price.
        // But the buggy version returns the raw oracle price directly, which might be different if transform is not applied.
        // Actually with PASSTHROUGH transform returns the same price, so we need a different payoff to see the difference.
        // Let's use a payoff that transforms the price, e.g., double it.
        // Since we can't re-initialize, we deploy a fresh contract with a different payoff.
        // Instead, we use a mock that returns different values on currentVersion vs atVersion? No.
        // We need a payoff type that actually changes the price, like Fixed18 base.
        // But we can't change the payoff after initialization.
        // Let's use a different approach: the bug is that transform is not called, so any payoff that is NOT identity will produce different results.
        // However, we initialized with PASSTHROUGH which IS identity, so both versions return the same.
        // To expose the bug, we need a payoff that alters the price.
        // We can deploy two contracts: one with the buggy code and one with the correct code, but we only have one contract source.
        // Since the test must pass on reference and fail on buggy version, and the reference always applies transform,
        // we can set up a payoff that does transform the price and then assert the returned price matches the expected transformed value.
        // The issue is that C's initialize is complex and requires a controller. We already faked it.
        // Let's choose a payoff that multiplies by 2.
        // We'll use PayoffType.CONSTANT with data signing? No, constant returns a fixed value.
        // PASSTHROUGH with direction NONE returns the same price, so no difference.
        // We need a payoff that transforms, so we use PayoffType.FIXED18 with a base? Actually Fixed18 payoff might be identity.
        // The simplest non-identity is CONTRACT with a custom contract. But that requires an external contract.
        // Alternatively, we can use the PASSTHROUGH with a direction that changes sign? direction NONE is no change.
        // We can use SHORT direction which negates the price. Then transform returns -rawPrice, while buggy returns rawPrice.
        // So we set payoffDirection to SHORT.
        // Let's redeploy with SHORT.
        // We'll create a new C instance with the proper setup.
        // Since setUp already creates c, we can just re-deploy a new instance for test.
        // But we need a fresh setup for each fuzz run; we can do it in test body.
        // We'll deploy a new C and controller inside test.
        MockController controller2 = new MockController(address(this));
        C c2 = new C();
        vm.prank(address(controller2));
        c2.initialize(IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.SHORT,
                data: bytes30(0)
            }),
            oracle: oracle,
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(1e17),
            makerFee: UFixed18.wrap(1e16),
            takerFee: UFixed18.wrap(1e16),
            positionFee: UFixed18.wrap(1e16),
            makerLimit: UFixed18.wrap(10000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        }));
        IOracleProvider.OracleVersion memory v2 = c2.currentVersion();
        // The correct contract applies transform, so price should be -rawPrice (Fixed18.wrap(-rawPrice) but scaled to 1e18).
        // The buggy returns the raw price (positive). So we assert that the price is negative (since rawPrice > 0).
        assertTrue(Fixed18.unwrap(v2.price) < 0);
    }
}

